\label{cor:exp-Z4}
Let $G=[K;S]$ satisfy the nine CH conditions of Table~\ref{tab:exp-conditions}.
Then $G$ admits a $T/T^\dagger$ implementation of CCZ
(Definition~\ref{def:exp-CI}) if and only if the system
\begin{equation}\label{eq:exp-Z4half}
\gamma\cdot c\;\equiv\;\tfrac{1}{2}\lvert c\rvert-2x_1x_2x_3\pmod 4,
\qquad c=K^{\!\top}\vec x+S^{\!\top}\vec y,
\end{equation}
has a solution with $\gamma_j\in\{0,1\}$ for all~$j$.

\label{prop:exp-blockcriterion}
Let $c=K^{\!\top}\vec x+S^{\!\top}\vec y$, and let $c_b$ and $\gamma_b$ be the
restrictions of $c$ and the flip vector $\gamma$ to block~$b$ of
Corollary~\ref{cor:exp-blockform}. If $\Gamma_j=(-1)^{\gamma_j}$, then
\begin{equation}\label{eq:exp-blockcriterion}
\mathrm{sw}_\Gamma(c)
=\sum_b\bigl(\lvert \gamma_b+c_b\rvert-\lvert \gamma_b\rvert\bigr).
\end{equation}
Thus the pattern specified by $\Gamma$ is single-qubit transversal if and only if, for every $\vec x,\vec y$,
\begin{equation}\label{eq:exp-blockcriterion-mod16}
\sum_b\lvert \gamma_b+c_b\rvert\equiv
\sum_b\lvert \gamma_b\rvert+4x_1x_2x_3\pmod 8.
\end{equation}
If all conditions in Proposition~\ref{prop:exp-signed-overlaps} that contain a stabilizer row hold,
the left hand side is independent of $\vec y$ modulo $8$, and it suffices to check the following
equation for the eight $\vec x\in\mathbb{F}_2^3$:
\begin{equation}\label{eq:exp-block-logical-criterion}
\sum_b\lvert \gamma_b+(K^{\!\top}\vec x)_b\rvert
\equiv\sum_b\lvert \gamma_b\rvert+4x_1x_2x_3\pmod 8.
\end{equation}

Equations~\eqref{eq:exp-blockcriterion}--\eqref{eq:exp-block-logical-criterion} apply to the
Boolean block restrictions $c_b$ and $\gamma_b$ with no degree restriction.

\label{prop:exp-q48-tpattern}\label{prop:exp-tpattern}
Index the columns of $S_{\mathrm{FG48}}$ by their coordinates $(u,w)$ of~\eqref{eq:exp-blockform},
writing $u=(u_1,u_2,u_3,u_4)$ for the four rows of $A$ and $w$ for the coset label.
The $T/T^{\dagger}$ pattern of $\mathcal{Q}_{48}$ is obtained by evaluating the following polynomial.
Write $\mathrm{ev}_{\mathcal P}$ for the
evaluation map $p\mapsto(p(\beta))_{\beta\in\mathcal P}$.
\begin{equation}\label{eq:exp-tpattern}
\gamma(u,w)=u_3+w_1Q_1(u)+w_2Q_2(u),\qquad
\begin{aligned}
Q_1&=u_1+u_2+u_3+u_1u_3+u_2u_3+u_2u_4,\\
Q_2&=u_3+u_4+u_1u_2+u_1u_4+u_3u_4,
\end{aligned}
\end{equation}
The flip vector is $\gamma=\mathrm{ev}_{\mathcal P}(\gamma(u,w))\in\mathbb{F}_2^{48}$.
The flip vector has weight $22$. The resulting $26\,T+22\,T^\dagger$ pattern is a single-qubit transversal
implementation of logical CCZ for $\mathcal{Q}_{48}$.

\label{prop:exp-lb}
For $k=3$ and $d_Z\ge3$, no multiplicity-free code (Lemma~\ref{lem:exp-fiber}) satisfying the CH
conditions exists with $s\le5$ (equivalently $r=k+s\le8$). Hence every such code has $s\ge6$.

\label{thm:exp-floor38}
No CSS code with $k=3$ and $d_Z\ge3$ satisfying the nine CH conditions
(Theorem~\ref{thm:exp-NS}) exists with $n\le38$, at any stabilizer rank.

\label{lem:exp-xorlift}
For bits $a_1,\dots,a_m\in\{0,1\}$,
\begin{equation}\label{eq:exp-xorlift}
a_1\oplus\cdots\oplus a_m
\;=\;\sum_{\emptyset\ne T\subseteq\{1,\dots,m\}}(-2)^{|T|-1}\prod_{i\in T}a_i .
\end{equation}

Induct on $m$, starting from the two-bit case $a\oplus b=a+b-2ab$, with the induction hypothesis
\begin{equation*}
a_1\oplus\cdots\oplus a_{m-1}
\;=\;\sum_{\emptyset\ne T\subseteq\{1,\dots,m-1\}}(-2)^{|T|-1}\prod_{i\in T}a_i .
\end{equation*}
Let $a=a_m,\ b = a_1\oplus\cdots\oplus a_{m-1}$ and apply the two-bit case.

\label{cor:exp-xorweight}
For bits $a,b\in\{0,1\}$, $2ab=a+b-(a\oplus b)$.
Consequently, if $\xi$ and $\eta$ are binary strings of the same length, $\xi\oplus\eta$
denotes coordinatewise XOR, $\lvert \xi\rvert$ denotes Hamming weight, and $\wedge$
denotes entrywise product, then
\begin{equation}\label{eq:exp-weightxor}
\lvert \xi\oplus\eta\rvert=\lvert \xi\rvert+\lvert \eta\rvert-2\lvert\xi\wedge\eta\rvert.
\end{equation}
For binary strings $\xi,\xi',\eta,\eta'$ of the same length,
\begin{equation*}
\lvert(\xi\oplus\xi')\wedge\eta\wedge\eta'\rvert\equiv
\lvert\xi\wedge\eta\wedge\eta'\rvert+\lvert\xi'\wedge\eta\wedge\eta'\rvert\pmod2.
\end{equation*}
Setting $\eta'=\mathbf1$, the all-ones string, gives the same additivity for
$\lvert\xi\wedge\eta\rvert$, and setting $\eta=\eta'=\mathbf1$ gives it for $\lvert\xi\rvert$.

\label{lem:exp-coefficient-parity}
Let $\mathbb K$ be $\mathbb{Z}$ or $\mathbb{F}_2$, and let $F\colon\mathbb{F}_2^m\to\mathbb K$ have the multilinear expansion
$F=\sum_{R\subseteq\{1,\ldots,m\}}c_Rm_R$ with $c_R\in\mathbb K$, where
$m_R(v)=\prod_{i\in R}v_i$. If $\mathbf1_{T'}$ is one on $T'$ and zero elsewhere, then
for every $T\subseteq\{1,\ldots,m\}$
\begin{equation}\label{eq:exp-topcoeff}
c_T=\sum_{T'\subseteq T}(-1)^{|T|-|T'|}F(\mathbf1_{T'}).
\end{equation}
In particular, for $\mathbb K=\mathbb{F}_2$ and $T=\{1,\ldots,m\}$, every sign equals $1$ and
$\mathbf1_{T'}$ runs over all of $\mathbb{F}_2^m$, so
\begin{equation}\label{eq:exp-topcoeff-parity}
c_{\{1,\ldots,m\}}=\sum_{v\in\mathbb{F}_2^m}F(v).
\end{equation}

